function chooseRandomItem(e){const t=Math.floor(Math.random()*e.length);return{index:t,item:e[t]}}function delay(e,t){return window.setTimeout(t,e)}function randomizeArray(e){const t=[];let r=0;for(;t.length<e.length&&r<1e3;){const{item:n,index:a}=chooseRandomItem(e);null!==n&&(t.push(n),e[a]=null,r=0),r+=1}return t}function repeatArray(e,t){let r=[];for(let n=0;n<t;n+=1)r=r.concat(e);return r}function removeRepeatingItems(e){return Array.from(new Set(e))}function formatAsTime(e){const t=1e3,r=6e4,n=36e5;let a="",o=0,c=0;switch(!0){case e>=n&&e<864e5:o=Math.trunc(e/n),c=e-o*n,a="h";break;case e>=r&&e<n:o=Math.trunc(e/r),c=e-o*r,a="m";break;case e<t:o=Math.trunc(e),c=0,a="ms";break;case e>=t&&e<r:default:o=Math.trunc(e/t),c=e-o*t,a="s";break}return 0===c?`${o}${a}`:`${o}${a}`+formatAsTime(c)}function numberWithCommas(e){return e?.toLocaleString("en-US",{maximumFractionDigits:0})}function convertToStandardFormat(e){if(null!==(e=`${e}`.replace(/,/g,"")).match(/^[0-9.]+$/gi)){const t=`${e=Math.round(Number(e))}`.length;let r=e;switch(!0){case t>4&&t<=5:r=`${Number(e/1e3).toFixed(2)} K`,e=r;break;case t>5&&t<=6:r=`${Number(e/1e3).toFixed(2)} K`,e=r;break;case t>6&&t<=9:r=`${Number(e/1e6).toFixed(2)} M`,e=r;break;case t>9&&t<=12:r=`${Number(e/1e9).toFixed(2)} B`,e=r;break;case t>12&&t<=15:r=`${Number(e/1e12).toFixed(2)} T`,e=r;break;case t>15&&t<=18:r=`${Number(e/1e15).toFixed(2)} aa`,e=r;break;default:e=numberWithCommas(e);break}}return e}function getDirectionVector(e,t=1,r=1,n=!0){const a=Math.sin(e*t)+Math.sin(e*r);let o=a/Math.abs(a);return n&&(o*=o>=0?t:r),o}